#define B0(x) (R32(x,2)^R32(x,13)^R32(x,22))
#define B1(x) (R32(x,6)^R32(x,11)^R32(x,25))
#define S0(x) (R32(x,7)^R32(x,18)^((x)>>3))
#define S1(x) (R32(x,17)^R32(x,19)^((x)>>10))

